python3 -I - <<'EOF'
import json, re, collections, os
p=os.path.expanduser('~/.claude/projects/-Users-franciscojavierjimenezbravo-dba-sgd-pitr/b1da6360-3672-4497-a7c7-fb0633facf0a.jsonl')
rows=[json.loads(l) for l in open(p,encoding='utf-8') if l.strip()]
ts=[r.get('timestamp') for r in rows if r.get('timestamp')]
print('registros:',len(rows),'| primero:',min(ts),'| ultimo:',max(ts))
tools=collections.Counter(); files_w=collections.defaultdict(list); bash_git=[]; first_write=None
user_bash=[]; user_msgs=0; denials=0
for r in rows:
    t=r.get('type'); m=r.get('message') or {}
    content=m.get('content')
    if t=='assistant' and isinstance(content,list):
        for c in content:
            if c.get('type')=='tool_use':
                n=c['name']; tools[n]+=1; inp=c.get('input',{})
                if n in('Write','Edit'):
                    fp=inp.get('file_path','')
                    if 'dba-sgd-pitr/' in fp and '/private/tmp' not in fp:
                        rel=fp.split('dba-sgd-pitr/')[1]; files_w[rel].append((r['timestamp'][11:16],n))
                        if first_write is None: first_write=(r['timestamp'],rel)
                if n=='Bash':
                    cmd=inp.get('command','')
                    for k in re.findall(r'git (commit|push[^\n;&|]*|rm|mv|add|filter-branch|update-ref)',cmd):
                        bash_git.append((r['timestamp'][11:16],k.strip()[:60]))
    if t=='user':
        txt = content if isinstance(content,str) else ' '.join(c.get('text','') for c in content if isinstance(c,dict) and c.get('type')=='text') if isinstance(content,list) else ''
        if '<bash-input>' in txt:
            user_bash.append((r['timestamp'][11:16], re.search(r'<bash-input>(.*?)</bash-input>',txt,re.S).group(1)[:110]))
        elif txt and not txt.startswith('<') and 'tool_result' not in str(content)[:40]:
            user_msgs+=1
        if isinstance(content,list):
            for c in content:
                if isinstance(c,dict) and c.get('type')=='tool_result' and 'denied by the Claude Code auto mode' in str(c.get('content','')): denials+=1
print('herramientas usadas por Claude Code:',dict(tools))
print('primera escritura de Claude en el proyecto:',first_write)
print('\n== archivos del proyecto escritos/editados por Claude Code (Write/Edit):')
for f,v in sorted(files_w.items()): print(f'  {f}: {len(v)} veces, primera {v[0][0]} UTC')
print('\n== operaciones git ejecutadas por Claude Code (Bash):')
c=collections.Counter(k.split()[0] for _,k in bash_git); print(' ',dict(c))
print('\n== comandos que ejecutaste tú en la terminal (<bash-input>):',len(user_bash))
for t,cmd in user_bash: print(f'  {t} UTC  {cmd}')
print('\nmensajes escritos por ti (aprox.):',user_msgs,'| acciones denegadas por el clasificador:',denials)
EOF

