python3 -I - <<'EOF'
import json, re, collections, os
p=os.path.expanduser('~/.claude/projects/-Users-franciscojavierjimenezbravo-dba-sgd-pitr/b1da6360-3672-4497-a7c7-fb0633facf0a.jsonl')
rows=[json.loads(l) for l in open(p,encoding='utf-8') if l.strip()]
proj=['ejecutar_recuperacion.sh','README.md','.gitignore','ai-logs/README.md','ai-logs/uso_de_ia.md','presentation/guion_presentacion.md','presentation/Volver_al_minuto_anterior_v4.pptx','presentation/Volver_al_minuto_anterior_v5.pptx','results/pruebas_objetivo','scripts/02_backup.sh','scripts/05_registros_posteriores.sh','scripts/07_reconciliar_post_incidente.sh','scripts/monitor.sh','scripts/03_cambios_legitimos.sh','Dockerfile','compose.demo.yaml','config/pgbackrest.conf','sql/']
hits=collections.defaultdict(list)
for r in rows:
    if r.get('type')!='assistant': continue
    for c in (r.get('message') or {}).get('content') or []:
        if c.get('type')=='tool_use' and c['name']=='Bash':
            cmd=c['input'].get('command','')
            writes = re.search(r"sed -i|open\(p,'w'|\.write\(|cp [^|]*(presentation|results)/|>> \.gitignore|chmod \+x|git mv|tar czf|xargs rm|git rm", cmd)
            if not writes: continue
            for f in proj:
                if f in cmd: hits[f].append(r['timestamp'][11:16])
for f in proj:
    v=hits.get(f)
    print(f'{f:52s} {"%d comando(s) de escritura, primero %s UTC"%(len(v),v[0]) if v else "nunca modificado por Claude vía terminal"}')
EOF
echo; echo "== Archivos que Claude nunca tocó: diferencias entre 0c502ea y main"; for f in Dockerfile compose.demo.yaml config/pgbackrest.conf sql/01_schema.sql sql/02_datos_iniciales.sql .env.example entorno-inicial.txt scripts/02_backup.sh scripts/05_registros_posteriores.sh scripts/07_reconciliar_post_incidente.sh; do printf '%-42s ' "$f"; git diff --shortstat 0c502ea main -- "$f" | sed 's/^ *//' | grep . || echo "sin cambios desde tu versión"; done

