    let rep = NSBitmapImageRep(cgImage: cg)
    try! rep.representation(using: .png, properties: [:])!.write(to: URL(fileURLWithPath: "\(a[2])/f\(i+1)_\(Int(dur*f))s.png"))
  }
}
print(dur)
EOF
