"""Redacta datos personales en copias de registros JSONL de Claude Code.

Uso: redactar_logs.py origen destino desde hasta [ventana_ini ventana_fin] [--telefono T]
  desde/hasta: líneas (1-based) del origen que se copian; hasta=0 => hasta el final (sin línea incompleta).
  ventana: líneas del origen con el ensayo personal (CV y aviso de empleo); se redacta su texto libre.
Imprime un resumen JSON con los conteos de redacción.
"""
import sys, re, json, hashlib

args = sys.argv[1:]
tel = None
if '--telefono' in args:
    k = args.index('--telefono'); tel = args[k + 1]; del args[k:k + 2]
src, dst, desde, hasta = args[0], args[1], int(args[2]), int(args[3])
win = (int(args[4]), int(args[5])) if len(args) >= 6 else None

PH_WIN = '[REDACTADO: ensayo personal con CV y aviso de empleo]'
# Claves que identifican la estructura del registro y no contienen texto libre
SEGURAS = {'type', 'name', 'id', 'tool_use_id', 'uuid', 'parentUuid', 'logicalParentUuid', 'sessionId', 'timestamp',
           'version', 'gitBranch', 'model', 'role', 'signature', 'requestId', 'media_type', 'stop_reason',
           'stop_sequence', 'userType', 'entrypoint', 'hash', 'shapeHash', 'promptId', 'messageId',
           'sourceToolAssistantUUID', 'sourceToolUseID', 'toolUseID', 'level', 'subtype', 'operation', 'mode',
           'permissionMode', 'service_tier', 'isSidechain', 'cwd'}

cnt = {'ventana_cadenas': 0, 'copias_fuera_de_ventana': 0, 'correo': 0, 'telefono': 0, 'linkedin': 0, 'comuna': 0}
recolectadas = set()

def redactar_ventana(o, clave=None):
    if isinstance(o, dict):
        return {k: (v if k in SEGURAS else redactar_ventana(v, k)) for k, v in o.items()}
    if isinstance(o, list):
        return [redactar_ventana(v, clave) for v in o]
    if isinstance(o, str) and o.strip():
        if len(o) >= 60:
            recolectadas.add(o)
        cnt['ventana_cadenas'] += 1
        return PH_WIN
    return o

RE_MAIL = re.compile(r'[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}')
PERMITIDOS = ('@anthropic.com', '@example.com', '@example.org')
RE_LINKEDIN = re.compile(r'(?:https?://)?(?:www\.)?linkedin\.com/in/[A-Za-z0-9_-]+')
RE_TEL = None
if tel:
    d = re.sub(r'\D', '', tel)[-8:]
    RE_TEL = re.compile(r'(?:\+?\s?56[\s.-]?)?9?[\s.-]?' + d[0] + r'[\s.-]?' + d[1:4] + r'[\s.-]?' + d[4:])

def limpiar_texto(s):
    for blk in recolectadas:
        if blk in s:
            s = s.replace(blk, PH_WIN); cnt['copias_fuera_de_ventana'] += 1
    def m(x):
        if x.group(0).lower().endswith(PERMITIDOS):
            return x.group(0)
        cnt['correo'] += 1; return '[CORREO REDACTADO]'
    s = RE_MAIL.sub(m, s)
    s, n = RE_LINKEDIN.subn('[PERFIL REDACTADO]', s); cnt['linkedin'] += n
    if RE_TEL:
        s, n = RE_TEL.subn('[TELEFONO REDACTADO]', s); cnt['telefono'] += n
    s, n = re.subn(r'[COMUNA REDACTADA]|\\u00d1u\\u00f1oa', '[COMUNA REDACTADA]', s); cnt['comuna'] += n
    return s

def limpiar(o):
    if isinstance(o, dict):
        return {k: limpiar(v) for k, v in o.items()}
    if isinstance(o, list):
        return [limpiar(v) for v in o]
    if isinstance(o, str):
        return limpiar_texto(o)
    return o

raw = open(src, 'rb').read().split(b'\n')
completas = []
for l in raw:
    if not l:
        continue
    try:
        json.loads(l); completas.append(l)
    except ValueError:
        break                                   # línea final aún en escritura: se descarta
fin = len(completas) if hasta == 0 else hasta
objs = [json.loads(l) for l in completas]
if win:
    for i in range(win[0] - 1, win[1]):
        objs[i] = redactar_ventana(objs[i])
salida = []
for i in range(desde - 1, fin):
    o = limpiar(objs[i])
    salida.append(json.dumps(o, ensure_ascii=False, separators=(',', ':')).encode('utf-8'))
out = b'\n'.join(salida) + b'\n'
for l in out.splitlines():
    json.loads(l)
open(dst, 'wb').write(out)
ultimo = next((objs[i].get('timestamp') for i in range(fin - 1, -1, -1) if objs[i].get('timestamp')), None)
print(json.dumps({'archivo': dst.rsplit('/', 1)[1], 'lineas': [desde, fin], 'total_origen': len(completas),
                  'ultimo_timestamp': ultimo, 'sha256': hashlib.sha256(out).hexdigest(), **cnt}, ensure_ascii=False))

