"""Redacta datos personales en copias de registros JSONL de Claude Code, sin tocar el contenido técnico.

Uso: redactar_logs.py origen destino desde hasta fuentes.txt [--telefono T]
  desde/hasta: líneas (1-based) del origen que se copian; hasta=0 => hasta el final (sin línea incompleta).
  fuentes.txt: texto del CV, del aviso de empleo y de la narración personal derivada de ellos.

Una cadena se considera personal si comparte fragmentos de 30 caracteres con las fuentes, o si es el
adjunto o la ruta de esos PDF; esa cadena completa se reemplaza. Luego se redactan correos, teléfono,
perfil de LinkedIn y comuna en todas las cadenas. Las líneas sin cambios se conservan byte a byte.
"""
import sys, re, json, hashlib

args = sys.argv[1:]
tel = None
if '--telefono' in args:
    k = args.index('--telefono'); tel = args[k + 1]; del args[k:k + 2]
src, dst, desde, hasta, fuentes = args[0], args[1], int(args[2]), int(args[3]), args[4]

PH = '[REDACTADO: ensayo personal con CV y aviso de empleo]'
SEGURAS = {'type', 'name', 'id', 'tool_use_id', 'uuid', 'parentUuid', 'logicalParentUuid', 'sessionId', 'timestamp',
           'version', 'gitBranch', 'model', 'role', 'signature', 'requestId', 'media_type', 'stop_reason',
           'userType', 'entrypoint', 'hash', 'shapeHash', 'promptId', 'messageId', 'leafUuid',
           'sourceToolAssistantUUID', 'sourceToolUseID', 'toolUseID', 'level', 'subtype', 'operation'}
N = 30
def norm(s): return re.sub(r'\s+', ' ', s)
texto_fuentes = norm(open(fuentes, encoding='utf-8').read())
TEJAS = {texto_fuentes[i:i + N] for i in range(0, len(texto_fuentes) - N + 1)}
RE_RUTA = re.compile(r'/Users/[^"\n]*?(?:Curriculum/[^"\n]*?|Ficha Aviso de Trabajo[^"\n]*?)\.pdf')

cnt = {'cadenas_personales': 0, 'rutas': 0, 'correo': 0, 'telefono': 0, 'linkedin': 0, 'comuna': 0}

def es_personal(s):
    if len(s) < N or (len(s) > 2000 and ' ' not in s[:2000]):
        return False                                  # cadenas cortas o base64 de imágenes
    t = norm(s); hits = 0
    for i in range(0, len(t) - N + 1, 7):
        if t[i:i + N] in TEJAS:
            hits += 1
            if hits >= 2:
                return True
    return False

RE_MAIL = re.compile(r'[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}')
PERMITIDOS = ('@anthropic.com', '@example.com', '@example.org')
RE_LINKEDIN = re.compile(r'(?:https?://)?(?:www\.)?linkedin\.com/in/[A-Za-z0-9_-]+')
RE_TEL = None
if tel:
    d = re.sub(r'\D', '', tel)[-8:]
    RE_TEL = re.compile(r'(?:\+?\s?56[\s.-]?)?9?[\s.-]?' + d[0] + r'[\s.-]?' + d[1:4] + r'[\s.-]?' + d[4:])

def limpiar_texto(s):
    if es_personal(s):
        cnt['cadenas_personales'] += 1
        return PH
    s, n = RE_RUTA.subn('[RUTA PERSONAL REDACTADA]', s); cnt['rutas'] += n
    def m(x):
        if x.group(0).lower().endswith(PERMITIDOS):
            return x.group(0)
        cnt['correo'] += 1; return '[CORREO REDACTADO]'
    s = RE_MAIL.sub(m, s)
    s, n = RE_LINKEDIN.subn('[PERFIL REDACTADO]', s); cnt['linkedin'] += n
    if RE_TEL:
        s, n = RE_TEL.subn('[TELEFONO REDACTADO]', s); cnt['telefono'] += n
    s, n = re.subn('[COMUNA REDACTADA]', '[COMUNA REDACTADA]', s); cnt['comuna'] += n
    return s

def limpiar(o, clave=None):
    if isinstance(o, dict):
        # Adjunto de los PDF personales: se elimina su contenido completo
        if o.get('type') == 'file' and RE_RUTA.search(str(o.get('filename', ''))):
            cnt['cadenas_personales'] += 1
            return {'type': 'file', 'filename': '[RUTA PERSONAL REDACTADA]', 'content': PH}
        return {k: (v if k in SEGURAS else limpiar(v, k)) for k, v in o.items()}
    if isinstance(o, list):
        return [limpiar(v, clave) for v in o]
    if isinstance(o, str):
        return limpiar_texto(o)
    return o

raw = open(src, 'rb').read().split(b'\n')
completas = []
for l in raw:
    if not l:
        continue
    try:
        json.loads(l); completas.append(l)
    except ValueError:
        break                                   # línea final aún en escritura: se descarta
fin = len(completas) if hasta == 0 else hasta
salida = []; cambiadas = 0
for i in range(desde - 1, fin):
    o0 = json.loads(completas[i]); o = limpiar(o0)
    if o != o0:
        salida.append(json.dumps(o, ensure_ascii=False, separators=(',', ':')).encode('utf-8')); cambiadas += 1
    else:
        salida.append(completas[i])
out = b'\n'.join(salida) + b'\n'
for l in out.splitlines():
    json.loads(l)
open(dst, 'wb').write(out)
ultimo = next((json.loads(completas[i]).get('timestamp') for i in range(fin - 1, -1, -1)
               if json.loads(completas[i]).get('timestamp')), None)
print(json.dumps({'archivo': dst.rsplit('/', 1)[1], 'lineas': [desde, fin], 'total_origen': len(completas),
                  'ultimo_timestamp': ultimo, 'sha256': hashlib.sha256(out).hexdigest(),
                  'lineas_modificadas': cambiadas, **cnt}, ensure_ascii=False))

